using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using SmartCampusServicePortal.Data; using SmartCampusServicePortal.Models; namespace SmartCampusServicePortal.Controllers; public class ServiceRequestsController(ApplicationDbContext db):Controller{public async Task<IActionResult> Index()=>View(await db.ServiceRequests.OrderByDescending(x=>x.SubmissionDate).ToListAsync()); [HttpGet] public IActionResult Create()=>View(new ServiceRequest()); [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Create(ServiceRequest r){if(!ModelState.IsValid)return View(r);r.Status="Pending";r.SubmissionDate=DateTime.Now;db.Add(r);await db.SaveChangesAsync();TempData["Message"]="Request submitted.";return RedirectToAction(nameof(Index));} public async Task<IActionResult> Details(int id){var r=await db.ServiceRequests.FindAsync(id);return r==null?NotFound():View(r);} [HttpGet] public IActionResult Track()=>View(); [HttpPost] public async Task<IActionResult> Track(string rollNo)=>View(await db.ServiceRequests.Where(x=>x.StudentRollNo==rollNo).ToListAsync());}